select 'missing relation' kind, r obj from want_r where to_regclass('public.'||r) is null
union all select 'missing function', f from want_f where not exists (select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname=f)
union all select 'missing column', t||'.'||c from want_c where to_regclass('public.'||t) is not null and not exists (select 1 from information_schema.columns where table_schema='public' and table_name=t and column_name=c)
